#!/usr/bin/env node
// One contract, both sides: a stream schema (JSON) becomes the compiled side's encoder and record readers (TypeScript, compiled with the
// program) and the host's replay and record writers (JavaScript). Neither side is written by hand, so they cannot drift apart.
//
//   node packages/host-stream/src/gen.mjs <schema.json> --ts <out.ts> --js <out.js> [--check]
//
// --check compares instead of writing, and fails when a generated file is out of date.
//
// Schema:
//   name      the stream's name ("dom": DomStream, replayDom)
//   channel   its channel number
//   stream    the import path of src/stream.ts as the generated TypeScript file sees it
//   commands  [{ op, name, doc?, args: [{ name, type }] }], op from 16 (1 to 15 are the stream's own); type is handle, i32, bool,
//             atom (one word; the host sees the atom's text), str (offset and length in the flush's text), f64 (two words) or
//             handles, last only: a count and that many handles (the compiled side passes an array and the count to write; the
//             host's handler gets the flush's words, the first handle's index there, and the count)
//   records   [{ name, doc?, fields: [{ name, type, doc? }] }]: blocks the host writes and the compiled side reads in place; type is
//             i32, handle, bool or f64. Records are laid out one after another from the records' start, f64 fields 8-byte aligned.
//
// Order is the ABI: commands keep their op numbers, and fields are appended, never renumbered or reordered.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const WORDS = { handle: 1, i32: 1, bool: 1, atom: 1, str: 2, f64: 2, handles: 1 };
const FIELD_WORDS = { i32: 1, handle: 1, bool: 1, f64: 2 };
const TS_TYPE = { handle: "number", i32: "number", bool: "boolean", atom: "number", str: "string", f64: "number" };
const cap = (s) => s[0].toUpperCase() + s.slice(1);
const constName = (s) => s.replace(/([a-z0-9])([A-Z])/g, "$1_$2").toUpperCase();

/** The schema checked, with each record's field offsets (words from the records' start) and the records' total size. */
export function layout(schema) {
  if (!/^[a-z][a-zA-Z0-9]*$/.test(schema.name)) throw new Error(`schema name ${schema.name}: lower camel case`);
  const ops = new Set();
  for (const c of schema.commands) {
    if (!Number.isInteger(c.op) || c.op < 16) throw new Error(`command ${c.name}: op ${c.op} (16 and up; 1 to 15 are the stream's own)`);
    if (ops.has(c.op)) throw new Error(`command ${c.name}: op ${c.op} is taken`);
    ops.add(c.op);
    for (const a of c.args) if (!(a.type in WORDS)) throw new Error(`command ${c.name}: argument ${a.name} has type ${a.type}`);
    if (c.args.some((a, i) => a.type === "handles" && i !== c.args.length - 1)) throw new Error(`command ${c.name}: handles must be the last argument`);
  }
  let at = 0;
  const records = (schema.records ?? []).map((r) => {
    const fields = r.fields.map((f) => {
      if (!(f.type in FIELD_WORDS)) throw new Error(`record ${r.name}: field ${f.name} has type ${f.type}`);
      if (f.type === "f64" && at % 2 === 1) at++;
      const field = { ...f, at };
      at += FIELD_WORDS[f.type];
      return field;
    });
    if (at % 2 === 1) at++;
    return { ...r, fields };
  });
  return { ...schema, records, recordWords: at };
}

const doc = (text, indent) => (text ? `${indent}/** ${text} */\n` : "");

export function generateTs(input) {
  const s = layout(input);
  const Name = cap(s.name);
  let out = `// Generated by packages/host-stream/src/gen.mjs from ${s.source ?? "the schema"}. Do not edit.\n`;
  out += `import { HostStream } from "${s.stream}";\n\n`;
  out += `/** The ${s.name} stream's channel. */\nexport const ${constName(s.name)}_CHANNEL = ${s.channel};\n`;
  out += `/** Words the host's records take after the commands. */\nexport const ${constName(s.name)}_RECORD_WORDS = ${s.recordWords};\n\n`;
  for (const r of s.records) for (const f of r.fields) {
    out += `export const ${constName(r.name)}_${constName(f.name)} = ${f.at};\n`;
  }
  out += `\n${doc(s.doc, "")}export class ${Name}Stream extends HostStream {\n`;
  out += `  constructor(commandWords: number) {\n    super(${constName(s.name)}_CHANNEL, commandWords, ${constName(s.name)}_RECORD_WORDS);\n  }\n`;
  for (const c of s.commands) {
    const size = 2 + c.args.reduce((n, a) => n + WORDS[a.type], 0);
    const list = c.args.find((a) => a.type === "handles");
    const params = c.args.map((a) => a.type === "handles" ? `${a.name}: number[], ${a.name}Count: number` : `${a.name}: ${TS_TYPE[a.type]}`);
    out += `\n${doc(c.doc, "  ")}  ${c.name}(${params.join(", ")}): void {\n`;
    out += list ? `    const at = this.reserve(${size} + ${list.name}Count);\n` : `    const at = this.reserve(${size});\n`;
    const hasStr = c.args.some((a) => a.type === "str");
    out += `    const w = this.words;\n`;
    out += list ? `    w[at] = ${c.op};\n    w[at + 1] = ${size - 2} + ${list.name}Count;\n` : `    w[at] = ${c.op};\n    w[at + 1] = ${size - 2};\n`;
    let k = 2;
    for (const a of c.args) {
      if (a.type === "str") { out += `    w[at + ${k}] = this.str(${a.name});\n    w[at + ${k + 1}] = ${a.name}.length;\n`; }
      else if (a.type === "f64") { out += `    this.f64(at + ${k}, ${a.name});\n`; }
      else if (a.type === "bool") { out += `    w[at + ${k}] = ${a.name} ? 1 : 0;\n`; }
      else if (a.type === "handles") {
        out += `    w[at + ${k}] = ${a.name}Count;\n`;
        out += `    for (let i = 0; i < ${a.name}Count; i++) w[at + ${k + 1} + i] = ${a.name}[i]!;\n`;
      }
      else out += `    w[at + ${k}] = ${a.name};\n`;
      k += WORDS[a.type];
    }
    void hasStr;
    out += `  }\n`;
  }
  for (const r of s.records) for (const f of r.fields) {
    const fn = `${r.name}${cap(f.name)}`;
    const read = f.type === "f64" ? `this.recordF64(${f.at})` : f.type === "bool" ? `this.recordWord(${f.at}) !== 0` : `this.recordWord(${f.at})`;
    out += `\n${doc(f.doc ?? `${r.name}.${f.name}, as the host last wrote it.`, "  ")}  ${fn}(): ${f.type === "bool" ? "boolean" : "number"} {\n    return ${read};\n  }\n`;
  }
  out += `}\n`;
  return out;
}

export function generateJs(input) {
  const s = layout(input);
  const Name = cap(s.name);
  let out = `// Generated by packages/host-stream/src/gen.mjs from ${s.source ?? "the schema"}. Do not edit.\n\n`;
  out += `export const ${constName(s.name)}_CHANNEL = ${s.channel};\n`;
  out += `const f64 = new Float64Array(1), f64Words = new Int32Array(f64.buffer);\n`;
  out += `const readF64 = (w, i) => { f64Words[0] = w[i]; f64Words[1] = w[i + 1]; return f64[0]; };\n\n`;
  out += `/**\n * Runs the commands in words [at, end) of a ${s.name} stream flush: each one calls its handler on \`h\` with its arguments (atoms as\n * their text, strings cut from \`text\`). Returns how many commands ran.\n */\n`;
  out += `export function replay${Name}(w, at, end, text, atoms, h) {\n  let n = 0;\n  while (at < end) {\n    switch (w[at]) {\n`;
  out += `      case 1: atoms[w[at + 2]] = text.substring(w[at + 3], w[at + 3] + w[at + 4]); break;\n`;
  for (const c of s.commands) {
    let k = 2;
    const args = c.args.map((a) => {
      let e;
      if (a.type === "str") e = `text.substring(w[at + ${k}], w[at + ${k}] + w[at + ${k + 1}])`;
      else if (a.type === "atom") e = `atoms[w[at + ${k}]]`;
      else if (a.type === "bool") e = `w[at + ${k}] !== 0`;
      else if (a.type === "f64") e = `readF64(w, at + ${k})`;
      else if (a.type === "handles") e = `w, at + ${k + 1}, w[at + ${k}]`;
      else e = `w[at + ${k}]`;
      k += WORDS[a.type];
      return e;
    });
    out += `      case ${c.op}: h.${c.name}(${args.join(", ")}); break;\n`;
  }
  out += `      default: if (h.unknown) h.unknown(w[at], w, at); else throw new Error(\`${s.name} stream: unknown command \${w[at]}\`);\n`;
  out += `    }\n    at += 2 + w[at + 1];\n    n++;\n  }\n  return n;\n}\n`;
  for (const r of s.records) {
    out += `\n/** The ${r.name} record's field offsets (words from the records' start). */\nexport const ${constName(r.name)} = { ${r.fields.map((f) => `${f.name}: ${f.at}`).join(", ")} };\n`;
    for (const f of r.fields) {
      const fn = `set${cap(r.name)}${cap(f.name)}`;
      const body = f.type === "f64" ? `floats[(base + ${f.at}) >> 1] = v;` : f.type === "bool" ? `words[base + ${f.at}] = v ? 1 : 0;` : `words[base + ${f.at}] = v;`;
      out += `export function ${fn}(words, floats, base, v) { ${body} }\n`;
    }
  }
  return out;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const args = process.argv.slice(2);
  const opt = (name) => { const i = args.indexOf(name); return i < 0 ? null : args[i + 1]; };
  const schemaPath = args[0];
  const schema = { ...JSON.parse(fs.readFileSync(schemaPath, "utf8")), source: path.basename(schemaPath) };
  const outputs = [[opt("--ts"), generateTs(schema)], [opt("--js"), generateJs(schema)]].filter(([p]) => p);
  let stale = 0;
  for (const [p, text] of outputs) {
    if (args.includes("--check")) {
      if (!fs.existsSync(p) || fs.readFileSync(p, "utf8") !== text) { console.error(`${p} is out of date: run gen.mjs`); stale++; }
    } else fs.writeFileSync(p, text);
  }
  process.exit(stale ? 1 : 0);
}
